targets.rawSql:
SELECT "Temperature" AS "Value"
FROM garmin."ActivityWeather" WHERE "ActivityID" = ${Activity:sqlstring}
ORDER BY time

SELECT "FeelsLike" AS "Value"
FROM garmin."ActivityWeather" WHERE "ActivityID" = ${Activity:sqlstring}
ORDER BY time

SELECT "Humidity" AS "Value"
FROM garmin."ActivityWeather" WHERE "ActivityID" = ${Activity:sqlstring}
ORDER BY time

SELECT "Wind" AS "Value"
FROM garmin."ActivityWeather" WHERE "ActivityID" = ${Activity:sqlstring}
ORDER BY time

SELECT time AS "Time", "Index" AS "Lap", "Distance" / 1609.344 AS "Distance", "Elapsed_Time" AS "Duration", "Elapsed_Time" / NULLIF("Distance" / 1609.344, 0) AS "Pace", "Avg_HR" AS "Avg HR", "Max_HR" AS "Max HR", "Ascent" * 3.28084 AS "Ascent", "Descent" * 3.28084 AS "Descent", ("Ascent" - "Descent") * 3.28084 AS "Net elevation"
FROM garmin."ActivityLap" WHERE "ActivityID" = ${Activity:sqlstring}
ORDER BY time

SELECT time AS "Time", "Latitude" AS "lat"
FROM garmin."ActivityGPS" WHERE "ActivityID" = ${Activity:sqlstring}
ORDER BY time

SELECT time AS "Time", "Longitude" AS "lon"
FROM garmin."ActivityGPS" WHERE "ActivityID" = ${Activity:sqlstring}
ORDER BY time

SELECT time AS "Time", "HeartRate" AS "HR"
FROM garmin."ActivityGPS" WHERE "ActivityID" = ${Activity:sqlstring}
ORDER BY time

SELECT time AS "Time", "Speed" * 2.23694 AS "Speed (mph)"
